    /// <summary>Checks the assets generated by RetroFPS/Build Penitent without running gameplay.</summary>
    public sealed class PenitentPrefabTests
    {
        private const string EnemyPath = "Assets/_Project/Prefabs/Enemies/Enemy_Penitent_Kefaretci.prefab";
        private const string WavePath = "Assets/_Project/Prefabs/Enemies/Penitent_Shockwave.prefab";
        private GameObject _prefab;
        private GameObject _instance;

        /// <summary>Loads the prefab, explicitly skipping until the builder has generated it.</summary>
        [SetUp]
        public void LoadPrefab()
        {
            _prefab = AssetDatabase.LoadAssetAtPath<GameObject>(EnemyPath);
            if (_prefab == null) Assert.Ignore("Penitent prefab has not been built. Run RetroFPS/Build Penitent first.");
        }

        /// <summary>Destroys any ray-test instance, including when an assertion failed.</summary>
        [TearDown]
        public void DestroyInstance()
        {
            if (_instance != null) Object.DestroyImmediate(_instance);
        }

