        /// <summary>Ensures the art can be replaced without removing gameplay components.</summary>
        [Test]
        public void VisualContainsOnlyArt()
        {
            Transform visual = Required("Visual");
            Assert.That(visual.GetComponentsInChildren<Collider>(true), Is.Empty);
            Assert.That(visual.GetComponentsInChildren<MonoBehaviour>(true), Is.Empty);
        }

        /// <summary>Requires the driver contracts, controller dimensions, droppers and AI references.</summary>
        [Test]
        public void RootContractsAndReferencesAreAssigned()
        {
            PenitentAI ai = _prefab.GetComponent<PenitentAI>();
            Assert.That(ai, Is.Not.Null);
            Assert.That(ai, Is.InstanceOf<IEncounterEnemy>());
            Assert.That(ai, Is.InstanceOf<IThreatCost>());
            Assert.That(ai, Is.InstanceOf<IEliteScalable>());
            Assert.That(ai, Is.InstanceOf<IStunnable>());
            PenitentView view = _prefab.GetComponent<PenitentView>();
            Assert.That(view, Is.Not.Null);
            var data = new SerializedObject(ai);
            Assert.That(Reference(data, "view"), Is.SameAs(view));
            EnemyHealthDropper health = _prefab.GetComponent<EnemyHealthDropper>();
            EnemyAmmoDropper ammo = _prefab.GetComponent<EnemyAmmoDropper>();
            Assert.That(health, Is.Not.Null);
            Assert.That(ammo, Is.Not.Null);
            Assert.That(Reference(data, "healthDropper"), Is.SameAs(health));
            Assert.That(Reference(data, "ammoDropper"), Is.SameAs(ammo));
            CharacterController controller = _prefab.GetComponent<CharacterController>();
            Assert.That(controller, Is.Not.Null);
            Assert.That(controller.height, Is.EqualTo(2f).Within(0.0001f));
            Assert.That(controller.radius, Is.EqualTo(0.45f).Within(0.0001f));
            Assert.That(controller.center, Is.EqualTo(new Vector3(0f, 1f, 0f)));
        }

        /// <summary>Requires all view references and renderer arrays for the placeholder presentation.</summary>
        [Test]
        public void ViewIsFullyWired()
        {
            PenitentView view = _prefab.GetComponent<PenitentView>();
            Assert.That(view, Is.Not.Null);
            var data = new SerializedObject(view);
            string[] names = { "visualRoot", "shieldPivot", "hitboxRoot", "shieldCenterSocket",
                "slamImpactSocket", "headSocket", "deathFxSocket", "slamAreaOutline", "slamAreaFill", "slamAreaImpact", "telegraphLight" };
            foreach (string name in names) Assert.That(Reference(data, name), Is.Not.Null, name);
            foreach (string name in new[] { "tintRenderers", "glowRenderers" })
            {
                SerializedProperty array = data.FindProperty(name);
                Assert.That(array, Is.Not.Null, name);
                Assert.That(array.arraySize, Is.GreaterThan(0), name);
                for (int i = 0; i < array.arraySize; i++)
                {
                    Renderer renderer = array.GetArrayElementAtIndex(i).objectReferenceValue as Renderer;
                    Assert.That(renderer, Is.Not.Null, name);
                    Assert.That(renderer.transform.IsChildOf(Required("Visual")), Is.True, name);
                }
            }
            SerializedProperty colliders = data.FindProperty("shieldColliders");
            Collider[] authored = Required("Hitboxes/Hitbox_Shield").GetComponentsInChildren<Collider>(true);
            Assert.That(colliders.arraySize, Is.EqualTo(4));
            Assert.That(authored.Length, Is.EqualTo(colliders.arraySize));
            for (int i = 0; i < colliders.arraySize; i++)
            {
                var collider = colliders.GetArrayElementAtIndex(i).objectReferenceValue as Collider;
                Assert.That(collider, Is.Not.Null);
                CollectionAssert.Contains(authored, collider);
            }
            Assert.That(data.FindProperty("shieldCollider"), Is.Null);
            foreach (string area in new[] { "SlamArea_Outline", "SlamArea_Fill", "SlamArea_Impact" })
                Assert.That(Required("Telegraph/" + area).gameObject.activeSelf, Is.False);
        }

        /// <summary>Requires an independent owner-wired lid hitbox following the replaceable lid.</summary>
        [Test]
        public void ShieldAndSocketsFollowModelTargets()
        {
            Transform shield = Required("Hitboxes/Hitbox_Shield");
            Assert.That(shield.GetComponent<Collider>(), Is.Null);
            Collider[] pieces = shield.GetComponentsInChildren<Collider>(true);
            Assert.That(pieces.Length, Is.EqualTo(4));
            foreach (Collider piece in pieces)
                // Prefab-asset objects count as inactive, so the lookup must include inactive parents.
                Assert.That(piece.GetComponentInParent<IDamageable>(true), Is.SameAs(shield.GetComponent<ShieldPlate>()));
            ShieldPlate plate = shield.GetComponent<ShieldPlate>();
            Assert.That(plate, Is.Not.Null);
            Assert.That(((IDamageProxy)plate).DamageOwner, Is.SameAs(_prefab.GetComponent<PenitentAI>()));
            Assert.That(Reference(new SerializedObject(plate), "owner"), Is.SameAs(_prefab.GetComponent<PenitentAI>()));
            SocketFollow follow = shield.GetComponent<SocketFollow>();
            Assert.That(follow, Is.Not.Null);
            Assert.That(follow.Target, Is.SameAs(Required("Visual/Placeholder/ShieldPivot")));
            Transform sockets = Required("Sockets");
            foreach (Transform socket in sockets)
            {
                SocketFollow socketFollow = socket.GetComponent<SocketFollow>();
                Assert.That(socketFollow, Is.Not.Null, socket.name);
                Assert.That(socketFollow.Target, Is.Null, socket.name);
            }
        }

        /// <summary>The small face collider forwards to its owner and has an optional head-bone binding.</summary>
        [Test]
        public void FaceWeakPointIsTinyAndWired()
        {
            Transform face = Required("Hitboxes/Hitbox_Face");
            PenitentWeakPoint weakPoint = face.GetComponent<PenitentWeakPoint>();
            Assert.That(weakPoint, Is.Not.Null);
            Assert.That(((IDamageProxy)weakPoint).DamageOwner, Is.SameAs(_prefab.GetComponent<PenitentAI>()));
            Assert.That(Reference(new SerializedObject(weakPoint), "owner"), Is.SameAs(_prefab.GetComponent<PenitentAI>()));
            SphereCollider sphere = face.GetComponent<SphereCollider>();
            Assert.That(sphere, Is.Not.Null);
            Assert.That(sphere.radius, Is.GreaterThan(0f).And.LessThanOrEqualTo(0.08f));
            SocketFollow follow = face.GetComponent<SocketFollow>();
            Assert.That(follow, Is.Not.Null);
            Assert.That(follow.Target, Is.Null);
            Transform mark = Required("Visual/Placeholder/Face_Mark");
            Assert.That(mark.GetComponent<Renderer>(), Is.Not.Null);
            Assert.That(mark.GetComponent<Collider>(), Is.Null);
        }

