        /// <summary>Standing-eye centre rays reach the face first through the visor at all required distances.</summary>
        [TestCase(3f)]
        [TestCase(6f)]
        [TestCase(12f)]
        public void VisorCentreRay_HitsFaceFirst(float distance)
        {
            CreateRayInstance();
            Transform face = _instance.transform.Find("Hitboxes/Hitbox_Face");
            Vector3 eye = new Vector3(0f, 1.7f, distance);
            Vector3 ray = face.position - eye;
            Assert.That(Physics.Raycast(eye, ray.normalized, out RaycastHit hit, ray.magnitude + 0.1f,
                ~0, QueryTriggerInteraction.Ignore), Is.True);
            Assert.That(hit.collider.transform, Is.SameAs(face));
        }

        /// <summary>Shots just outside the tiny opening hit a shield piece before any head collider.</summary>
        [TestCase(0f, 0.12f)]
        [TestCase(0f, -0.12f)]
        [TestCase(0.12f, 0f)]
        [TestCase(-0.12f, 0f)]
        public void VisorOffsetRay_HitsShieldFirst(float x, float y)
        {
            CreateRayInstance();
            Transform shield = _instance.transform.Find("Hitboxes/Hitbox_Shield");
            Vector3 centre = _instance.transform.Find("Hitboxes/Hitbox_Face").position;
            Vector3 eye = new Vector3(0f, 1.7f, 6f);
            Vector3 ray = centre + new Vector3(x, y, 0f) - eye;
            Assert.That(Physics.Raycast(eye, ray.normalized, out RaycastHit hit, ray.magnitude + 0.1f,
                ~0, QueryTriggerInteraction.Ignore), Is.True);
            Assert.That(hit.collider.transform.IsChildOf(shield), Is.True, hit.collider.name);
        }

        private void CreateRayInstance()
        {
            _instance = Object.Instantiate(_prefab, Vector3.zero, Quaternion.identity);
            Physics.SyncTransforms();
        }

        /// <summary>Area quads are transparent unlit, outlined on all sides and hidden until charging.</summary>
        [Test]
        public void TelegraphIsVisibleAndDefaultsOff()
        {
            Assert.That(_prefab.transform.Find("Telegraph/Glint"), Is.Null);
            Assert.That(_prefab.transform.Find("Telegraph/SlamLine"), Is.Null);
            foreach (string name in new[] { "SlamArea_Outline", "SlamArea_Fill", "SlamArea_Impact" })
            {
                Transform quad = Required("Telegraph/" + name);
                Assert.That(quad.gameObject.activeSelf, Is.False);
                Material material = quad.GetComponent<Renderer>().sharedMaterial;
                Assert.That(material.shader.name, Is.EqualTo("Universal Render Pipeline/Unlit"));
                Assert.That(material.GetFloat("_Surface"), Is.EqualTo(1f));
                Assert.That(material.GetFloat("_ZWrite"), Is.Zero);
                Assert.That(material.renderQueue, Is.EqualTo(3000));
                Assert.That(material.GetColor("_BaseColor").a, Is.InRange(0.01f, 0.99f));
            }
            Transform outline = Required("Telegraph/SlamArea_Outline");
            foreach (string edge in new[] { "Near", "Far", "Left", "Right" })
                Assert.That(outline.Find(edge).GetComponent<Renderer>(), Is.Not.Null);
            Light light = Required("Telegraph/TelegraphLight").GetComponent<Light>();
            Assert.That(light.type, Is.EqualTo(LightType.Point));
            Assert.That(light.range, Is.EqualTo(6f));
            Assert.That(light.shadows, Is.EqualTo(LightShadows.None));
            Assert.That(light.enabled, Is.False);
            var data = new SerializedObject(_prefab.GetComponent<PenitentView>());
            SerializedProperty glows = data.FindProperty("glowRenderers");
            SerializedProperty tints = data.FindProperty("tintRenderers");
            foreach (Renderer lid in Required("Visual/Placeholder/ShieldPivot").GetComponentsInChildren<Renderer>(true))
            {
                bool bound = false;
                for (int i = 0; i < glows.arraySize; i++)
                    bound |= glows.GetArrayElementAtIndex(i).objectReferenceValue == lid;
                Assert.That(bound, Is.True, lid.name);
                for (int i = 0; i < tints.arraySize; i++)
                    Assert.That(tints.GetArrayElementAtIndex(i).objectReferenceValue, Is.Not.SameAs(lid));
            }
        }

