        /// <summary>The cached rectangle remains world-fixed and the fill grows from its near edge.</summary>
        [Test]
        public void AreaTelegraph_AnchorsFillAndKeepsImpactAfterChargeEnds()
        {
            _instance = Object.Instantiate(_prefab, Vector3.zero, Quaternion.identity);
            PenitentView view = _instance.GetComponent<PenitentView>();
            InvokeView(view, "Awake");
            view.ResetVisual();
            Vector3 origin = new Vector3(20f, 0f, 20f);
            view.BeginSlamTelegraph(1.1f, origin, Vector3.forward, 6.5f, 4.5f);
            Transform outline = _instance.transform.Find("Telegraph/SlamArea_Outline");
            Transform fill = _instance.transform.Find("Telegraph/SlamArea_Fill");
            Transform impact = _instance.transform.Find("Telegraph/SlamArea_Impact");
            Assert.That(outline.gameObject.activeSelf, Is.True);
            Assert.That(outline.lossyScale.y, Is.EqualTo(6.5f).Within(0.0001f));
            Assert.That(fill.lossyScale.y, Is.Zero);
            typeof(PenitentView).GetField("_windupElapsed", BindingFlags.Instance | BindingFlags.NonPublic).SetValue(view, 0.55f);
            _instance.transform.SetPositionAndRotation(new Vector3(4f, 1f, 3f), Quaternion.Euler(0f, 35f, 0f));
            InvokeView(view, "Render");
            Assert.That(outline.position.x, Is.EqualTo(origin.x).Within(0.0001f));
            Assert.That(outline.position.z, Is.EqualTo(origin.z + 3.25f).Within(0.0001f));
            Assert.That(fill.lossyScale.y, Is.EqualTo(3.25f).Within(0.0001f));
            Assert.That(fill.position.z, Is.EqualTo(origin.z + 1.625f).Within(0.0001f));
            view.PlaySlamImpact();
            view.EndSlamTelegraph();
            Assert.That(outline.gameObject.activeSelf, Is.False);
            Assert.That(fill.gameObject.activeSelf, Is.False);
            Assert.That(impact.gameObject.activeSelf, Is.True);
            typeof(PenitentView).GetField("_impactRemaining", BindingFlags.Instance | BindingFlags.NonPublic).SetValue(view, 0.125f);
            InvokeView(view, "Render");
            var block = new MaterialPropertyBlock();
            impact.GetComponent<Renderer>().GetPropertyBlock(block);
            Assert.That(block.GetColor("_BaseColor").a, Is.EqualTo(0.45f).Within(0.0001f));
            view.ResetVisual();
            Assert.That(impact.gameObject.activeSelf, Is.False);
            view.PlaySlamImpact();
            view.PlayDeath();
            Assert.That(impact.gameObject.activeSelf, Is.False);
        }

        /// <summary>All four shield pieces disable together during guard-down, stun and death, then restore on reset.</summary>
        [Test]
        public void ShieldPieces_FollowGuardStateTogether()
        {
            _instance = Object.Instantiate(_prefab, Vector3.zero, Quaternion.identity);
            PenitentView view = _instance.GetComponent<PenitentView>();
            InvokeView(view, "Awake");
            Collider[] shields = _instance.transform.Find("Hitboxes/Hitbox_Shield").GetComponentsInChildren<Collider>(true);
            view.ResetVisual();
            foreach (Collider collider in shields) Assert.That(collider.enabled, Is.True);
            view.SetGuardLowered(true);
            foreach (Collider collider in shields) Assert.That(collider.enabled, Is.False);
            view.SetGuardLowered(false);
            foreach (Collider collider in shields) Assert.That(collider.enabled, Is.True);
            view.SetStunned(true);
            foreach (Collider collider in shields) Assert.That(collider.enabled, Is.False);
            view.SetStunned(false);
            foreach (Collider collider in shields) Assert.That(collider.enabled, Is.True);
            view.PlayDeath();
            foreach (Collider collider in shields) Assert.That(collider.enabled, Is.False);
            view.ResetVisual();
            foreach (Collider collider in shields) Assert.That(collider.enabled, Is.True);
        }

        private static void InvokeView(PenitentView view, string method) => typeof(PenitentView)
            .GetMethod(method, BindingFlags.Instance | BindingFlags.NonPublic).Invoke(view, null);

        /// <summary>Repeated configuration retains every generated GameObject and component for stable prefab IDs.</summary>
        [Test]
        public void Builder_ReusesExistingChildrenAndComponents()
        {
            GameObject instance = Object.Instantiate(_prefab);
            try
            {
                ConfigureInMemory(instance);
                Component[] before = instance.GetComponentsInChildren<Component>(true);
                ConfigureInMemory(instance);
                CollectionAssert.AreEqual(before, instance.GetComponentsInChildren<Component>(true));
            }
            finally { Object.DestroyImmediate(instance); }
        }

        /// <summary>Migration removes only obsolete charge children and the monolithic shield collider.</summary>
        [Test]
        public void Builder_RemovesLegacyLayoutAndKeepsOtherComponents()
        {
            _instance = Object.Instantiate(_prefab);
            ConfigureInMemory(_instance);
            Transform telegraph = _instance.transform.Find("Telegraph");
            foreach (string name in new[] { "Glint", "SlamLine" })
            {
                var stale = new GameObject(name);
                stale.transform.SetParent(telegraph, false);
            }
            Transform shield = _instance.transform.Find("Hitboxes/Hitbox_Shield");
            BoxCollider legacy = shield.gameObject.AddComponent<BoxCollider>();
            PenitentAI ai = _instance.GetComponent<PenitentAI>();
            Transform head = _instance.transform.Find("Hitboxes/Hitbox_Head");
            Renderer lid = _instance.transform.Find("Visual/Placeholder/ShieldPivot/Shield_Lid").GetComponent<Renderer>();
            ConfigureInMemory(_instance);
            Assert.That(telegraph.Find("Glint"), Is.Null);
            Assert.That(telegraph.Find("SlamLine"), Is.Null);
            Assert.That(legacy == null, Is.True);
            Assert.That(shield.GetComponentsInChildren<Collider>(true).Length, Is.EqualTo(4));
            Assert.That(_instance.GetComponent<PenitentAI>(), Is.SameAs(ai));
            Assert.That(_instance.transform.Find("Hitboxes/Hitbox_Head"), Is.SameAs(head));
            Assert.That(_instance.transform.Find("Visual/Placeholder/ShieldPivot/Shield_Lid").GetComponent<Renderer>(), Is.SameAs(lid));
        }

        /// <summary>Both custom-mode triggers preserve art bindings, optional placeholders and assigned bone targets.</summary>
        [TestCase(false, false)]
        [TestCase(false, true)]
        [TestCase(true, false)]
        [TestCase(true, true)]
        public void Builder_PreservesCustomVisual(bool animatorOnly, bool omitPlaceholder)
        {
            GameObject instance = Object.Instantiate(_prefab);
            try
            {
                ConfigureInMemory(instance);
                Transform visual = instance.transform.Find("Visual");
                var model = new GameObject(animatorOnly ? "UserArt" : "Model");
                model.transform.SetParent(visual, false);
                model.transform.localPosition = new Vector3(1f, 2f, 3f);
                Renderer renderer = model.AddComponent<MeshRenderer>();
                PenitentView view = instance.GetComponent<PenitentView>();
                var data = new SerializedObject(view);
                foreach (string field in new[] { "tintRenderers", "glowRenderers" })
                {
                    SerializedProperty array = data.FindProperty(field);
                    array.arraySize = 1;
                    array.GetArrayElementAtIndex(0).objectReferenceValue = renderer;
                }
                data.FindProperty("shieldPivot").objectReferenceValue = model.transform;
                Animator animator = animatorOnly ? model.AddComponent<Animator>() : null;
                data.FindProperty("animator").objectReferenceValue = animator;
                data.ApplyModifiedPropertiesWithoutUndo();
                SocketFollow[] follows = instance.GetComponentsInChildren<SocketFollow>(true);
                foreach (SocketFollow follow in follows) follow.SetTarget(model.transform);
                Transform placeholder = visual.Find("Placeholder");
                placeholder.gameObject.SetActive(false);
                if (omitPlaceholder) Object.DestroyImmediate(placeholder.gameObject);
                BoxCollider shieldPiece = instance.transform.Find("Hitboxes/Hitbox_Shield/Shield_Lid").GetComponent<BoxCollider>();
                shieldPiece.size = new Vector3(0.3f, 0.4f, 0.5f);
                shieldPiece.center = Vector3.one;
                Component[] before = instance.GetComponentsInChildren<Component>(true);
                ConfigureInMemory(instance);
                CollectionAssert.AreEqual(before, instance.GetComponentsInChildren<Component>(true));
                Assert.That(shieldPiece.size, Is.EqualTo(new Vector3(0.3f, 0.4f, 0.5f)));
                Assert.That(shieldPiece.center, Is.EqualTo(Vector3.one));
                Assert.That(model.transform.localPosition, Is.EqualTo(new Vector3(1f, 2f, 3f)));
                Assert.That(visual.Find("Placeholder") == null, Is.EqualTo(omitPlaceholder));
                if (!omitPlaceholder) Assert.That(placeholder.gameObject.activeSelf, Is.False);
                data.Update();
                Assert.That(Reference(data, "shieldPivot"), Is.SameAs(model.transform));
                Assert.That(Reference(data, "animator"), Is.EqualTo(animator));
                foreach (string field in new[] { "tintRenderers", "glowRenderers" })
                    Assert.That(data.FindProperty(field).GetArrayElementAtIndex(0).objectReferenceValue, Is.SameAs(renderer));
                foreach (SocketFollow follow in follows) Assert.That(follow.Target, Is.SameAs(model.transform));
                if (animatorOnly) Assert.That(visual.Find("Model"), Is.Null);
            }
            finally { Object.DestroyImmediate(instance); }
        }

        /// <summary>Custom models retain any existing shield collision, including a resized legacy root box.</summary>
        [Test]
        public void Builder_PreservesCustomRootShieldCollider()
        {
            _instance = Object.Instantiate(_prefab);
            ConfigureInMemory(_instance);
            var model = new GameObject("Model");
            model.transform.SetParent(_instance.transform.Find("Visual"), false);
            Transform shield = _instance.transform.Find("Hitboxes/Hitbox_Shield");
            foreach (Collider piece in shield.GetComponentsInChildren<Collider>(true)) Object.DestroyImmediate(piece);
            BoxCollider custom = shield.gameObject.AddComponent<BoxCollider>();
            custom.size = new Vector3(2f, 3f, 0.4f);
            ConfigureInMemory(_instance);
            Assert.That(shield.GetComponentsInChildren<Collider>(true), Is.EqualTo(new Collider[] { custom }));
            Assert.That(custom.size, Is.EqualTo(new Vector3(2f, 3f, 0.4f)));
            var data = new SerializedObject(_instance.GetComponent<PenitentView>());
            Assert.That(data.FindProperty("shieldColliders").arraySize, Is.EqualTo(1));
            Assert.That(data.FindProperty("shieldColliders").GetArrayElementAtIndex(0).objectReferenceValue, Is.SameAs(custom));
        }

        /// <summary>Rebind respects inactive ancestor chains, finds shields case-insensitively and retains a fallback glow.</summary>
        [Test]
        public void Rebind_UsesActivePrefabArtAndPreservesGlowFallback()
        {
            GameObject instance = Object.Instantiate(_prefab);
            try
            {
                ConfigureInMemory(instance);
                Transform visual = instance.transform.Find("Visual");
                visual.Find("Placeholder").gameObject.SetActive(false);
                var model = new GameObject("Model");
                model.transform.SetParent(visual, false);
                var shield = new GameObject("sHiElD");
                shield.transform.SetParent(model.transform, false);
                Renderer renderer = shield.AddComponent<MeshRenderer>();
                InvokeBuilder("RebindRenderers", new object[] { instance });
                var data = new SerializedObject(instance.GetComponent<PenitentView>());
                // Shield/lid art is tinted through the glow list only, never in both lists.
                Assert.That(data.FindProperty("tintRenderers").arraySize, Is.EqualTo(0));
                Assert.That(data.FindProperty("glowRenderers").GetArrayElementAtIndex(0).objectReferenceValue, Is.SameAs(renderer));
                shield.name = "BodyArt";
                InvokeBuilder("RebindRenderers", new object[] { instance });
                data.Update();
                Assert.That(data.FindProperty("tintRenderers").arraySize, Is.EqualTo(1));
                Assert.That(data.FindProperty("tintRenderers").GetArrayElementAtIndex(0).objectReferenceValue, Is.SameAs(renderer));
                Assert.That(data.FindProperty("glowRenderers").GetArrayElementAtIndex(0).objectReferenceValue, Is.SameAs(renderer));
            }
            finally { Object.DestroyImmediate(instance); }
        }

        private static void ConfigureInMemory(GameObject root)
        {
            GameObject ghoul = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Project/Prefabs/Enemies/Enemy_Ghoul_Stalker.prefab");
            // Null materials affect only this disposable clone; persistent art and assets are never saved.
            InvokeBuilder("ConfigureEnemy", new object[] { root, ghoul, null, null, null, null, null, null, null, null });
        }

        private static void InvokeBuilder(string method, object[] arguments)
        {
            Type builder = Type.GetType("RetroFPS.Editor.PenitentBuilder, RetroFPS.Editor", true);
            builder.GetMethod(method, BindingFlags.Static | BindingFlags.NonPublic).Invoke(null, arguments);
        }

        /// <summary>Requires distinct head and back damage zones wired to the root driver.</summary>
        [TestCase("Hitboxes/Hitbox_Head", 2f, true)]
        [TestCase("Hitboxes/Hitbox_Back", 1.5f, false)]
        public void DamageZonesAreWired(string path, float multiplier, bool critical)
        {
            Transform zone = Required(path);
            Hitbox hitbox = zone.GetComponent<Hitbox>();
            Assert.That(hitbox, Is.Not.Null);
            Assert.That(zone.GetComponent<Collider>(), Is.Not.Null);
            Assert.That(hitbox.DamageMultiplier, Is.EqualTo(multiplier));
            Assert.That(hitbox.IsCriticalZone, Is.EqualTo(critical));
            Assert.That(Reference(new SerializedObject(hitbox), "targetEntityComponent"), Is.SameAs(_prefab.GetComponent<PenitentAI>()));
        }

        private Transform Required(string path)
        {
            Transform child = _prefab.transform.Find(path);
            Assert.That(child, Is.Not.Null, "Run RetroFPS/Build Penitent first: " + path);
            return child;
        }

        private static Object Reference(SerializedObject data, string name)
        {
            SerializedProperty property = data.FindProperty(name);
            Assert.That(property, Is.Not.Null, name);
            return property.objectReferenceValue;
        }
    }
}
